INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('e5fbe326-7f29-4962-92f2-4b0aa1b2726e', '8fa2d12b-24a6-4d3b-8c12-62e88f4a89dc', 'Virtual Host Builder', 'Create /etc/nginx/sites-available/mysite.conf with a server block listening on port 9090, root /var/www/mysite. Create /var/www/mysite/index.html with "Hello Custom". Enable the site with ln -s and reload nginx. Run: curl -s localhost:9090. What is the content?', 100, '$2b$10$aA5mV.iIB6SZamhjp46XaewDDXOlQlvb4DVHZjgyVBrxZPuaT9nkq');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('43f1ac22-33ef-4026-ad37-c7124cb47a80', '8fa2d12b-24a6-4d3b-8c12-62e88f4a89dc', 'Reverse Proxy', 'Start a python http server on port 8888: python3 -m http.server 8888 &. Create nginx reverse proxy config on port 9091 proxying to localhost:8888. Reload nginx. Run: curl -s localhost:9091. What HTML title is shown?', 100, '$2b$10$4F4OT00zxrm5gxNI5cULkeTi.NMojmldMGIGKpqJXkkKQEutTAECy');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('d138aa99-9ebf-471d-bc06-388e6c741b07', '8fa2d12b-24a6-4d3b-8c12-62e88f4a89dc', 'SSL Generator', 'Create /etc/nginx/ssl/ directory. Generate self-signed cert: openssl req -x509 -nodes -days 365 -newkey rsa:2048 -keyout /etc/nginx/ssl/key.pem -out /etc/nginx/ssl/cert.pem -subj "/CN=localhost". Run: openssl x509 -in /etc/nginx/ssl/cert.pem -noout -subject. What is the CN value?', 100, '$2b$10$ZdZmQhi1wMFaDXYfCNykXe82jDbJYAHpZYw7m767jLHVkr1Op2ItS');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('50dbd7a1-83f4-43b0-84f7-8b08f1979b04', '8fa2d12b-24a6-4d3b-8c12-62e88f4a89dc', 'Rate Limiter', 'Add to your nginx server config: limit_req_zone $binary_remote_addr zone=one:10m rate=1r/s;. Then add limit_req zone=one burst=5 nodelay to a location block. Reload. Run: for i in 1 2 3 4 5 6; do curl -s -o /dev/null -w "%{http_code} " localhost:9090; done. What HTTP codes appear (space-separated)?', 100, '$2b$10$SLTngPfBB3RMt4t8mGCNP.tcUdTyqM7RVy1FKH15WC21rR2qVGF8.');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('63b73147-0e05-4930-a7b4-f6d00571322e', '8fa2d12b-24a6-4d3b-8c12-62e88f4a89dc', 'Gzip Optimizer', 'Add gzip on; gzip_types text/plain; to the http block in /etc/nginx/nginx.conf. Reload nginx. Run: curl -s -H "Accept-Encoding: gzip" -D - localhost 2>&1 | grep -i content-encoding. What encoding is shown?', 100, '$2b$10$amsV2vZGoXWpWFwlKAS1/eE5qlqjne52LATfAeORWoO5xNqNVIEsu');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('78bb3b2e-e800-489f-961c-1ad3aace98ac', '8fa2d12b-24a6-4d3b-8c12-62e88f4a89dc', 'Load Balancer', 'Start 2 python servers on ports 8889 and 8890 (python3 -m http.server 8889 & and python3 -m http.server 8890 &). Create nginx upstream config on port 9092 load balancing between them. Reload and curl localhost:9092. What is the upstream block name you used?', 100, '$2b$10$jeSWa0uPMmv4GQ3/WhH0DOKEmzf36PQMHMey/qw6rDbHd9xXTs96q');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('e7861173-a724-4238-a8c1-ad49ada7a9f7', '8fa2d12b-24a6-4d3b-8c12-62e88f4a89dc', 'Access Control', 'Create a location block for /private with "allow 127.0.0.1; deny all;". Reload nginx. Run: curl -s -o /dev/null -w "%{http_code}" localhost:9090/private. What status code?', 100, '$2b$10$FbhKMzwrhmPiPq8fvRBEleszOhRTsGoJtyNrIIUzEeididbiaOWMG');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('8f1af12c-d92a-4984-b472-606abd89a3ce', '8fa2d12b-24a6-4d3b-8c12-62e88f4a89dc', 'Error Page Customizer', 'Create /var/www/mysite/404.html with "Page Not Found". Add error_page 404 /404.html to your server block. Reload. Run: curl -s localhost:9090/nonexistent. What is the content?', 100, '$2b$10$9LZ62EF36eIVaR5j65owPOLVz/0iRoEltb0EYd0zbpwOpi0gLRSAK');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('3bf9369d-20c1-434c-9e14-5811296372a5', '8fa2d12b-24a6-4d3b-8c12-62e88f4a89dc', 'Log Analyzer', 'Make 5 requests to nginx. Then run: cat /var/log/nginx/access.log | tail -5 | wc -l. How many access log entries?', 75, '$2b$10$f3AhXXwLVhgNUm/vE5TnjeLLUlxZLrTOWG5kdV1QdGvpZ.jT5KENK');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('f4b78164-3ce7-4cd6-b1b2-3ad53d483c60', '8fa2d12b-24a6-4d3b-8c12-62e88f4a89dc', 'Rewrite Master', 'Add to your server config: location /old { return 301 /new; }. Create /var/www/mysite/new.html with "Redirected". Reload. Run: curl -s localhost:9090/old. What is the content after redirect?', 100, '$2b$10$Hy/L1MHcafqClwDB8KyBWeZunZJeI1nNjtUtBpHh9FX4gC0qRUBQ6');
